namespace mal{using ll=long long;using ull=unsigned long long;using ld=long double;using cpx=std::complex<double>;using std::vector;constexpr double PI=3.141592653589793238462643383279502884;inline int glim(std::size_t x){return x<=1?1:2<<(31^__builtin_clz((int)x-1));}namespace common_detail{__attribute__((used))int(*const glim_kept)(std::size_t)=&glim;}}namespace mal{template<int MOD>struct mint{int v;mint(ll v_=0):v(int(v_%MOD)){if(v<0)v+=MOD;}friend mint operator+(mint a,mint b){const int r=a.v+b.v;return mint(r>=MOD?r-MOD:r,unchecked{});}friend mint operator-(mint a,mint b){const int r=a.v-b.v;return mint(r<0?r+MOD:r,unchecked{});}friend mint operator*(mint a,mint b){return mint(int((ll)a.v*b.v%MOD),unchecked{});}mint&operator+=(mint b){return*this=*this+b;}mint&operator-=(mint b){return*this=*this-b;}mint&operator*=(mint b){return*this=*this*b;}mint pow(ll k)const{mint r=1,a=*this;for(;k;k>>=1,a*=a)if(k&1)r*=a;return r;}mint inv()const{return pow(MOD-2);}bool operator==(mint b)const{return v==b.v;}bool operator!=(mint b)const{return v!=b.v;}private:struct unchecked{};mint(int v_,unchecked):v(v_){}};}
